class Pipeline:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def _filter_nulls(data):
        return [item for item in data if item is not None]

    @staticmethod
    def _normalize_strings(data):
        return [item.strip().lower() if isinstance(item, str) else item for item in data]

    @staticmethod
    def _deduplicate(data):
        seen = set()
        result = []
        for item in data:
            if item not in seen:
                seen.add(item)
                result.append(item)
        return result

    @staticmethod
    def _sort_items(data):
        return sorted(data)

    @staticmethod
    def _pipe(data, transforms):
        for func in transforms:
            data = func(data)
        return data

    def run(self):
        transforms = [
            self._filter_nulls,
            self._normalize_strings,
            self._deduplicate,
            self._sort_items,
        ]
        return self._pipe(self.data, transforms)
